={{ JSON.stringify({
  model: "deepseek-chat",
  messages: [
    {
      role: "system",
      content: "Ты строгий классификатор. Отвечай ТОЛЬКО одной заглавной латинской буквой без пробелов и знаков:\nA — bug (ошибка, сбой, падение, баг)\nB — task (рутинная задача, настройка, доступ, вопрос)\nC — feature (новый функционал, улучшение, пожелание) D — unclear (если в задаче смешаны разные типы, например баг и фича одновременно, или не хватает данных)"
    },
    {
      role: "user",
      content: $json.text || $json.body?.text || JSON.stringify($json)
    }
  ],
  max_tokens: 1,
  temperature: 0.8,
  logprobs: true,
  top_logprobs: 5
}) }}

parameters.jsCode:
const response = $input.item.json;

const logprobsContent = response?.choices?.[0]?.logprobs?.content?.[0];
const topLogprobs = logprobsContent?.top_logprobs || [];

const map = { A: "bug", B: "task", C: "feature", D: "unclear" };
const probs = { bug: 0, task: 0, feature: 0, unclear: 0 };

if (topLogprobs.length > 0) {
  for (const item of topLogprobs) {
    const token = (item.token || "").trim().toUpperCase();
    if (map[token]) {
      probs[map[token]] += Math.exp(item.logprob);
    }
  }
} else {
  const rawLetter = (response?.choices?.[0]?.message?.content || "").trim().toUpperCase();
  if (map[rawLetter]) {
    probs[map[rawLetter]] = 1;
  }
}

const total = probs.bug + probs.task + probs.feature + probs.unclear || 1;
const normalized = {
  bug: probs.bug / total,
  task: probs.task / total,
  feature: probs.feature / total,
  unclear: probs.unclear / total
};

let bestType = "unclear";
let bestConfidence = 0;

for (const [type, conf] of Object.entries(normalized)) {
  if (conf > bestConfidence) {
    bestType = type;
    bestConfidence = conf;
  }
}

if (bestType === "unclear") {
  bestConfidence = 0;
}

return {
  json: {
    type: bestType,
    confidence: Number(bestConfidence.toFixed(4)),
    probabilities: {
      bug: Number(normalized.bug.toFixed(4)),
      task: Number(normalized.task.toFixed(4)),
      feature: Number(normalized.feature.toFixed(4)),
      unclear: Number(normalized.unclear.toFixed(4))
    }
  }
};
